// credentialsHaveDebug reports whether the credentials table (as it stands in
// s's database) carries the debug column — the PRAGMA read the migration's
// guard itself uses.
func credentialsHaveDebug(t *testing.T, s *Store) bool {
	t.Helper()
	rows, err := s.db.QueryContext(context.Background(), "PRAGMA table_info(credentials)")
	if err != nil {
		t.Fatalf("PRAGMA table_info(credentials): %v", err)
	}
	defer rows.Close()
	for rows.Next() {
		var (
			cid     int
			name    string
			ctype   string
			notnull int
			dflt    sql.NullString
			pk      int
		)
		if err := rows.Scan(&cid, &name, &ctype, &notnull, &dflt, &pk); err != nil {
			t.Fatalf("scan table_info row: %v", err)
		}
		if name == "debug" {
			return true
		}
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("table_info rows: %v", err)
	}
	return false
}

// mintDebugDevice plants one device credential row with a fixed hash — the
// ListDevices probe the migration assertions read back through.
func mintDebugDevice(t *testing.T, s *Store, tokenHash string) {
	t.Helper()
	if err := s.InsertDeviceCredential(context.Background(), tokenHash, "CODE1", time.Now()); err != nil {
		t.Fatalf("InsertDeviceCredential: %v", err)
	}
}

// TestDeviceDebugColumnMigration covers android-tv-app 3.1's store duty: the
// credentials.debug column exists via the ensureColumn idiom — fresh DBs get
// it from the CREATE TABLE, pre-existing DBs gain it at Open with existing
// rows reading the DEFAULT 0 — and the flip setter round-trips through the
// kind='device' guard.
func TestDeviceDebugColumnMigration(t *testing.T) {
	ctx := context.Background()

	t.Run("fresh_db_has_column_and_default", func(t *testing.T) {
		s := openStore(t)
		if !credentialsHaveDebug(t, s) {
			t.Fatalf("fresh credentials table carries no debug column")
		}
		mintDebugDevice(t, s, "a1b2c3d4fresh")
		toks, err := s.ListDevices(ctx)
		if err != nil {
			t.Fatalf("ListDevices: %v", err)
		}
		if len(toks) != 1 || toks[0].Debug {
			t.Fatalf("fresh device debug = %+v, want exactly one row at Debug false (the column DEFAULT)", toks)
		}
	})

	t.Run("preexisting_db_gains_column", func(t *testing.T) {
		dsn := filepath.Join(t.TempDir(), "legacy.db")
		legacy, err := Open(ctx, dsn)
		if err != nil {
			t.Fatalf("Open legacy: %v", err)
		}
		mintDebugDevice(t, legacy, "a1b2c3d4legacy")
		if _, err := legacy.db.ExecContext(ctx, "ALTER TABLE credentials DROP COLUMN debug"); err != nil {
			t.Fatalf("drop debug (simulate pre-3.1 DB): %v", err)
		}
		if err := legacy.Close(); err != nil {
			t.Fatalf("Close legacy: %v", err)
		}
		reopened, err := Open(ctx, dsn)
		if err != nil {
			t.Fatalf("re-Open (additive migration): %v", err)
		}
		defer reopened.Close()
		if !credentialsHaveDebug(t, reopened) {
			t.Fatalf("migrated credentials table carries no debug column")
		}
		// The pre-existing row reads the DEFAULT 0 — the migration never
		// flips a device (debug only ever becomes true through the admin
		// flip route).
		toks, err := reopened.ListDevices(ctx)
		if err != nil {
			t.Fatalf("ListDevices after migration: %v", err)
		}
		if len(toks) != 1 || toks[0].Debug {
			t.Fatalf("migrated device debug = %+v, want Debug false (DEFAULT backfill)", toks)
		}
		// Re-running Open on the ALREADY-migrated database must not error
		// (the guarded ALTER no-ops) — INV-idempotent-migration.
		again, err := Open(ctx, dsn)
		if err != nil {
			t.Fatalf("second re-Open (idempotent migration): %v", err)
		}
		if err := again.Close(); err != nil {
			t.Fatalf("Close after second re-Open: %v", err)
		}
	})

	t.Run("flip_roundtrip_and_kind_guard", func(t *testing.T) {
		s := openStore(t)
		mintDebugDevice(t, s, "a1b2c3d4flip")
		// A session credential (the accounts_test raw-SQL seed shape) — the
		// kind the flip setter must refuse.
		if _, err := s.db.ExecContext(ctx, `INSERT INTO credentials
			(kind, token_hash, user_id, label, created_at, expires_at)
			VALUES ('session', 'cafebabe', NULL, '', '2026-11-12T00:00:00Z', NULL)`); err != nil {
			t.Fatalf("seed session credential: %v", err)
		}
		toks, err := s.ListDevices(ctx)
		if err != nil {
			t.Fatalf("ListDevices: %v", err)
		}
		if len(toks) != 1 {
			t.Fatalf("ListDevices = %d rows, want only the device (kind filter)", len(toks))
		}
		rowID, err := strconv.ParseInt(toks[0].ID, 10, 64)
		if err != nil {
			t.Fatalf("device rowid %q: %v", toks[0].ID, err)
		}
		if err := s.SetDeviceDebug(ctx, rowID, true); err != nil {
			t.Fatalf("SetDeviceDebug true: %v", err)
		}
		toks, err = s.ListDevices(ctx)
		if err != nil {
			t.Fatalf("ListDevices after flip: %v", err)
		}
		if len(toks) != 1 || !toks[0].Debug {
			t.Fatalf("flipped device debug = %+v, want Debug true", toks)
		}
		// The kind='device' guard: a session credential addressed by its
		// rowid is an unknown device (the wrapped sql.ErrNoRows convention).
		var sessRowID int64
		if err := s.db.QueryRowContext(ctx,
			`SELECT id FROM credentials WHERE kind = 'session'`).Scan(&sessRowID); err != nil {
			t.Fatalf("locate session row: %v", err)
		}
		if err := s.SetDeviceDebug(ctx, sessRowID, true); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("SetDeviceDebug on session row = %v, want wrapped sql.ErrNoRows", err)
		}
	})
}
